/-- Cleanliness condition for a handshake given contamination sets. -/
def handshake_is_clean {V : Type*} {Γ : Type*} (h : Handshake V Γ) (t : Γ × Bool → Set V) : Prop := match h with
  | .single x a y => t a ⊆ {x} ∧ t (opp_glove_side a) ⊆ {y}
  | .double x a b y => a.1 ≠ b.1 ∧ t a ⊆ {x} ∧ t b ⊆ {y}

/-- Contamination update rule following a handshake. -/
def handshake_update_contam {V : Type*} {Γ : Type*} [DecidableEq Γ] (h : Handshake V Γ) (t : Γ × Bool → Set V) : Γ × Bool → Set V := fun s =>
    match h with
    | .single x a y =>
        if s = a then t a ∪ {x}
        else if s = opp_glove_side a then t (opp_glove_side a) ∪ {y}
        else t s
    | .double x a b y =>
        if s = a then t a ∪ {x}
        else if s = b then t b ∪ {y}
        else if s = opp_glove_side a ∨ s = opp_glove_side b then
          t (opp_glove_side a) ∪ t (opp_glove_side b)
        else t s

/-- Forcing predicate: `a` forces a monochromatic `K_k` if all sufficiently large complete graphs, under any `a`-bounded edge colouring, contain a monochromatic `K_k`. -/
