/-- The reachability relation between pairs of counter vectors for fixed control states in a 2-counter machine. -/
def two_counter_machine_reach_rel {Q : Type*} (M : TwoCounterMachine Q) (q q' : Q) : Set ((ℕ × ℕ) × (ℕ × ℕ)) :=
  { p | Relation.ReflTransGen (two_counter_machine_step M) (q, p.1) (q', p.2) }

/-- Predicate asserting that a 2-counter machine is a 2-VASS, having only update transitions. -/
def two_counter_machine_is_vass {Q : Type*} (M : TwoCounterMachine Q) : Prop :=
  ∀ t ∈ M.transitions, ∃ q w₁ w₂ q', t = (q, TwoCounterInstr.update w₁ w₂, q')

/-- Minimum number of states in an epsilon-free NFA accepting L whose transition graph is a bipartite cactus. -/
noncomputable def min_bipartite_cactus_nfa_states {α : Type*} (L : Language α) : ℕ := sInf { k : ℕ | ∃ (σ : Type) (_ : Fintype σ) (A : NFA α σ),
    Fintype.card σ = k ∧ A.accepts = L ∧ is_bipartite_cactus_nfa A }

declarations.reading:
For a type `α` and a language `L : Language α` (i.e., a set of lists of `α`), `min_bipartite_cactus_nfa_states L` is the infimum in `ℕ` of the set of all `k : ℕ` such that there exists a finite type `σ` and an NFA `A` with alphabet `α` and state type `σ` satisfying:
1. The cardinality of `σ` is `k`;
2. The language accepted by `A` is `L`;
3. `A` is a bipartite cactus NFA (`is_bipartite_cactus_nfa A`).

